/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field PriceUnit.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModulePriceUnit extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, PriceUnit);
}

public Set getAllowedValues()
{
    InventTableModule   inventTableModule;
    var                 ret = new Set(Types::Real);

    while select PriceUnit from inventTableModule
        group by PriceUnit
    {
        if (!ret.in(inventTableModule.PriceUnit))
        {
            ret.add(inventTableModule.PriceUnit);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, PriceUnit));
    qbr.value(queryValue(_value));
}
